CREATE TABLE `attendances` (
  `id` varchar(191) NOT NULL,
  `tenant_id` varchar(191) NOT NULL,
  `employee_id` varchar(191) NOT NULL,
  `date` date NOT NULL,
  `check_in_time` datetime(3) DEFAULT NULL,
  `check_in_lat` double DEFAULT NULL,
  `check_in_lng` double DEFAULT NULL,
  `check_out_time` datetime(3) DEFAULT NULL,
  `check_out_lat` double DEFAULT NULL,
  `check_out_lng` double DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  `check_in_distance` double DEFAULT NULL,
  `check_out_distance` double DEFAULT NULL,
  `status` enum('APPROVED','PENDING_REVIEW','REJECTED') NOT NULL DEFAULT 'APPROVED',
  `reviewed_by` varchar(191) DEFAULT NULL,
  `reviewed_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `attendances_employee_id_date_key` (`employee_id`,`date`),
  KEY `attendances_tenant_id_date_idx` (`tenant_id`,`date`),
  KEY `attendances_tenant_id_status_idx` (`tenant_id`,`status`),
  CONSTRAINT `attendances_employee_id_fkey` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `attendances_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
