INSERT INTO `employees` VALUES ('0f274d2c-1a87-4cb0-ba07-ddea21590435','ed2de3f5-d5b6-4f00-8549-c1078aba153a','923384c3-3ef5-4ffe-8947-31cbb819dc30','c17e31e0-ff8a-4f89-84d2-ec3f255aea77','James','Wilson','james@demo-salon.com','+1-555-0202','/api/uploads/avatars/employee-1772686783325-m0beni.jpg',NULL,'#10b981','Creci en un barrio donde los hombres no hablaban de estilo. Yo fui el primero en desafiar eso. Hoy, despues de 8 anos perfeccionando mi arte, cada tinte que mezclo lleva algo de mi alma. Me inspiran los atardeceres, la musica y esos clientes que llegan nerviosos y se van sintiendose invencibles.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,0,0,'2026-04-02 22:54:28.625','2026-04-20 22:14:21.311','32318491-48f3-4ffc-9dea-04a5a9df6666'),('1159832a-e27d-4a26-82c6-329a42c42703','12702c5d-46a1-4a80-b8d9-a85749222654','6fe2dbed-f56f-44c4-bc22-d9ff9a3c59da','f412a29b-4c73-410f-8790-b26e6c72d61e','prueba3','prueba3','prueba3@democontiental.com','+52 5557457457','/api/uploads/avatars/4bb8cda6-61d3-409e-8b2e-20a61a4dfc06.jpg','/api/uploads/avatars/fff9d41a-fc91-4ef1-86aa-a26d130cf3f4.jpg','#008080','prueba3','','','','','','','Barbero/a',1,0,0,0,'2026-04-14 19:57:50.029','2026-04-14 19:58:06.086',NULL),('1a7082d3-ea0c-4a50-8852-5c509891afac','12702c5d-46a1-4a80-b8d9-a85749222654','86f961e8-aaf3-4033-801c-ac29ed9d5460','f412a29b-4c73-410f-8790-b26e6c72d61e','Kevin','Moreno','kevin@democontinental.com','+52 3333333312','/api/uploads/avatars/892a1bb4-aba2-4f81-9e69-d3438442c312.jpeg','/api/uploads/avatars/f0bb198e-5d01-4554-953a-537c486ff806.jpeg','#008080','Me apasiona mi trabajo tanto como la vida misma. ','O-','Raquel','Moreno','3344443298','Hermano/a','','Barbero/a',1,0,0,0,'2026-04-13 21:20:57.919','2026-04-13 21:22:33.953',NULL),('279aaa3b-6cf7-4d1c-b2c0-d0b89c23caab','12702c5d-46a1-4a80-b8d9-a85749222654','4aeb9060-1f95-4b51-b8ce-063292b953c3','f412a29b-4c73-410f-8790-b26e6c72d61e','Diego','Martírez','Diego@democontinental.com','+52 33 2154 1403','/api/uploads/avatars/d5b97a45-3ffb-4558-a052-df00eeea179f.jpeg','/api/uploads/avatars/b1d08dc3-6c67-418a-966a-5d9a270dcb78.jpeg','#008080','Cuando  amamos lo que hacemos para vivir no podemos llamarlo trabajo si no pasión.','','','','','','','Barbero/a',1,0,0,0,'2026-04-02 23:31:02.561','2026-04-14 04:29:32.657',NULL),('2ba5bde6-18f5-43b6-a809-97096a786bd8','12702c5d-46a1-4a80-b8d9-a85749222654','3ecb2106-c463-4921-97e8-d4c3126797f9','f412a29b-4c73-410f-8790-b26e6c72d61e','Prueba','Prueba','prueba@democontinental.com','+52 43453465346','/api/uploads/avatars/1a32e5e3-612b-4a20-a5fc-b8a172edd295.jpg','/api/uploads/avatars/7db9cf22-2c30-43f0-a6e7-aea165cae4cc.jpg','#008080','prueba','A+','','','','','','Barbero/a',1,0,0,0,'2026-04-14 19:34:30.756','2026-04-14 19:35:07.278',NULL),('32318491-48f3-4ffc-9dea-04a5a9df6666','ed2de3f5-d5b6-4f00-8549-c1078aba153a','3ca3cbcd-5744-48f1-8a6b-766c3654fb48','c17e31e0-ff8a-4f89-84d2-ec3f255aea77','AdminSergio','Owner','admin@siliba.com','+1-555-0100','/api/uploads/avatars/a5160ca5-0842-4c04-a8cb-92cf1e7e5ead.jpg','/api/uploads/avatars/fd6f2d89-cc92-4bc7-abee-dd0c6a15abbb.jpg','#008080','Por tradicion y amor a esta profesion desde hace 20 años. ','A+','','','','','',NULL,1,0,0,0,'2026-04-12 06:53:12.119','2026-04-24 20:37:34.730',NULL),('4563a809-6e17-4833-a61e-85de897d3b98','12702c5d-46a1-4a80-b8d9-a85749222654','bca38ac7-81c2-49d9-a5f0-fe7ae1d14343','f412a29b-4c73-410f-8790-b26e6c72d61e','prueba2','prueba2','prueba2@democontinental.com','+52 3354364535','/api/uploads/avatars/6e197b0a-33be-4378-b446-0cf93629476f.jpg','/api/uploads/avatars/a6201261-3dcc-49ac-80d4-c8989f61a622.jpg','#008080','prueba de horario','A-','','','','','','Barbero/a',1,0,0,0,'2026-04-14 19:43:41.341','2026-04-14 19:44:46.912',NULL),('493374c4-45d6-47c7-8f42-6ac949ae8f20','12702c5d-46a1-4a80-b8d9-a85749222654','cc01dc7d-fbce-4ccc-8645-a5aba6da4841','f412a29b-4c73-410f-8790-b26e6c72d61e','Fernando','Velázquez','Fernando@democontinental.com','+52 3375845743','/api/uploads/avatars/d96f452a-a58f-4252-a0e4-66bf4e53429d.jpeg','/api/uploads/avatars/e7174c31-9815-4ec5-89f6-bc1aa21aa536.jpeg','#008080','Ser barbero es mi vocación, naci para esto. ','A+','','','','','','Barbero/a',1,0,0,0,'2026-04-14 04:26:57.962','2026-04-14 04:28:07.413',NULL),('7188c4a6-99b8-44d9-9b82-0959e054147c','12702c5d-46a1-4a80-b8d9-a85749222654','9a559c02-dd0e-47e0-8789-b7293bf2a284','f412a29b-4c73-410f-8790-b26e6c72d61e','Emiliano','García','Emiliano@democontinental.com','+52 3334566654','/api/uploads/avatars/30441705-7349-444b-8add-32ae3f129516.jpeg','/api/uploads/avatars/d660aa2b-da02-40ce-b374-cad900010ba6.jpeg','#008080','La navaja es una herramienta peligrosa y segura al mismo tiempo. ','B+','Maria','Ramirez','45645454545','Hermano/a','','Barbero/a',1,0,0,0,'2026-04-13 22:01:29.968','2026-04-13 22:02:46.078',NULL),('7b2b44ff-061b-4074-ae2c-fb1a341e942c','ed2de3f5-d5b6-4f00-8549-c1078aba153a','6ce839aa-901e-49a4-a13d-c78ce173c0c6','4ab7dad9-e09c-4e8a-865d-8b1ce52d9252','Sofia','Martinez','sofia@demo-salon.com','+1-555-0203','/api/uploads/avatars/employee-1772686783699-hoe75s.jpg',NULL,'#f59e0b','Mi abuela siempre decia: \"las manos hablan de quien eres\". Esas palabras me marcaron para siempre. Llevo 6 anos dedicada al cuidado personal y cada clienta que atiendo se convierte en familia. Un facial no es solo un tratamiento — es una hora donde el mundo se detiene y tu eres lo unico que importa.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,0,0,'2026-04-02 22:54:28.636','2026-04-20 22:14:07.993','32318491-48f3-4ffc-9dea-04a5a9df6666'),('8e1a6790-9765-458f-9630-c21b478fd7e1','ed2de3f5-d5b6-4f00-8549-c1078aba153a','89a47421-1dc8-4cf6-ab08-202bb5d569d3','c17e31e0-ff8a-4f89-84d2-ec3f255aea77','Maria','Garcia','maria@demo-salon.com','+1-555-0201','/api/uploads/avatars/employee-1772686782829-95dnt0.jpg','/api/uploads/avatars/0b4bd73c-ca37-40c0-b8c0-eed9bdcc4d4b.jpg','#6366f1','Tengo 10 años transformando vidas desde mi silla. Mi mama me ensenó que la belleza no es vanidad, es amor propio. Cada persona que se sienta frente a mi espejo llega con una historia, y mi trabajo es ayudarla a sentirse como la protagonista que es. No solo corto cabello — devuelvo sonrisas.','O+','','','','','','',1,0,0,0,'2026-04-02 22:54:28.609','2026-04-22 05:26:11.607','32318491-48f3-4ffc-9dea-04a5a9df6666');
