CREATE TABLE `notification_logs` (
  `id` varchar(191) NOT NULL,
  `tenant_id` varchar(191) NOT NULL,
  `template_id` varchar(191) DEFAULT NULL,
  `channel` enum('EMAIL','SMS','WHATSAPP','PUSH') NOT NULL,
  `event_name` varchar(191) NOT NULL,
